#!/usr/bin/env node
/**
 * render-contract.mjs — Render an NDA from a JSON deal file + Markdown template.
 *
 * Usage:
 *   node render-contract.mjs <deal.json> [--template <path>]
 *
 * Deal fields: partyA, partyB, effectiveDate, mutual (bool), termYears, carveouts (string[])
 *
 * Template syntax (minimal mustache-like):
 *   {{field}}          interpolate a scalar field
 *   {{#field}}...{{/field}}   include block only if field is truthy
 *   {{^field}}...{{/field}}   include block only if field is falsy
 *   {{carveoutsList}}  renders carveouts as a numbered list, or
 *                      the sentence "No carve-outs apply." when empty
 */

import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const DEFAULT_TEMPLATE = resolve(dirname(fileURLToPath(import.meta.url)), 'templates/nda.md');

/** Validate the deal object; throws a helpful Error on bad input. */
export function validateDeal(deal) {
  if (deal === null || typeof deal !== 'object' || Array.isArray(deal)) {
    throw new TypeError('Deal must be a JSON object with fields: partyA, partyB, effectiveDate, mutual, termYears, carveouts.');
  }

  for (const field of ['partyA', 'partyB', 'effectiveDate']) {
    const value = deal[field];
    if (typeof value !== 'string' || value.trim() === '') {
      throw new TypeError(
        `Missing required field "${field}": expected a non-empty string (e.g. ${JSON.stringify(field === 'effectiveDate' ? '2026-01-01' : 'Acme Corp')}).`
      );
    }
  }

  if (typeof deal.mutual !== 'boolean') {
    throw new TypeError('Field "mutual" is required and must be a boolean (true = both parties exchange confidential information).');
  }

  if (!Number.isInteger(deal.termYears) || deal.termYears < 1) {
    throw new RangeError(
      `Invalid termYears: ${JSON.stringify(deal.termYears)}. The confidentiality term must be a whole number of years greater than 0 — a term of 0 years would make the agreement expire immediately. Did you mean 1, 2, 5...?`
    );
  }

  if (!Array.isArray(deal.carveouts)) {
    throw new TypeError('Field "carveouts" is required and must be an array of strings (use [] if there are none).');
  }
  for (const [i, c] of deal.carveouts.entries()) {
    if (typeof c !== 'string' || c.trim() === '') {
      throw new TypeError(`carveouts[${i}] must be a non-empty string.`);
    }
  }
}

/** Render the numbered carve-out list (or the empty-case sentence). */
export function renderCarveouts(carveouts) {
  if (!Array.isArray(carveouts) || carveouts.length === 0) {
    return 'No carve-outs apply.';
  }
  return carveouts.map((c, i) => `${i + 1}. ${c}`).join('\n');
}

/** Expand the template against a validated deal. */
export function renderContract(deal, template) {
  validateDeal(deal);

  let out = template;

  // Conditional blocks: truthy {{#key}}...{{/key}}
  out = out.replace(/\{\{#(\w+)\}\}([\s\S]*?)\{\{\/\1\}\}/g, (_, key, body) =>
    Boolean(deal[key]) ? body : ''
  );
  // Inverted blocks: falsy {{^key}}...{{/key}}
  out = out.replace(/\{\{\^(\w+)\}\}([\s\S]*?)\{\{\/\1\}\}/g, (_, key, body) =>
    !deal[key] ? body : ''
  );

  // Scalar interpolation.
  const values = {
    ...Object.fromEntries(Object.entries(deal).filter(([, v]) => typeof v !== 'object')),
    carveoutsList: renderCarveouts(deal.carveouts),
  };
  out = out.replace(/\{\{(\w+)\}\}/g, (_, key) => {
    if (!(key in values)) throw new ReferenceError(`Unknown template placeholder "{{${key}}}".`);
    return String(values[key]);
  });

  // Tidy whitespace: collapse runs of blank lines, trim trailing space per line.
  out = out
    .split('\n')
    .map((line) => line.replace(/[ \t]+$/, ''))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return out + '\n';
}

function main(argv) {
  const args = argv.slice(2);
  const positional = [];
  let templatePath = DEFAULT_TEMPLATE;

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--template') {
      templatePath = resolve(args[++i]);
      if (!templatePath) throw new Error('--template requires a path argument.');
    } else if (args[i] === '--help' || args[i] === '-h') {
      console.log('Usage: node render-contract.mjs <deal.json> [--template <template.md>]');
      process.exit(0);
    } else {
      positional.push(args[i]);
    }
  }

  if (positional.length !== 1) {
    console.error('Usage: node render-contract.mjs <deal.json> [--template <template.md>]');
    process.exit(1);
  }

  let deal;
  try {
    deal = JSON.parse(readFileSync(positional[0], 'utf8'));
  } catch (err) {
    throw new Error(`Could not read deal file "${positional[0]}": ${err.message}`);
  }

  const template = readFileSync(templatePath, 'utf8');
  process.stdout.write(renderContract(deal, template));
}

if (process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/\\/g, '/').split('/').pop()) && process.env.NODE_TEST_CONTEXT === undefined) {
  try {
    main(process.argv);
  } catch (err) {
    console.error(`render-contract: ${err.message}`);
    process.exit(1);
  }
}

