import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { renderContract, renderCarveouts, validateDeal } from '../render-contract.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const template = readFileSync(resolve(here, '../templates/nda.md'), 'utf8');

const baseDeal = {
  partyA: 'Acme Corp',
  partyB: 'Globex LLC',
  effectiveDate: '2026-01-01',
  mutual: true,
  termYears: 2,
  carveouts: [],
};

test('mutual deal renders symmetric obligations for both parties', () => {
  const out = renderContract({ ...baseDeal }, template);

  assert.match(out, /^MUTUAL NON-DISCLOSURE AGREEMENT/m);
  // Symmetric language present.
  assert.match(out, /Each party may act as both a Disclosing Party and a Receiving Party/);
  // One-way sentence absent.
  assert.doesNotMatch(out, /Only Party B acts as a Receiving Party/);
});

test('one-way deal renders obligations only for partyB', () => {
  const out = renderContract({ ...baseDeal, mutual: false }, template);

  assert.match(out, /^NON-DISCLOSURE AGREEMENT/m);
  assert.doesNotMatch(out, /^MUTUAL NON-DISCLOSURE AGREEMENT/m);
  assert.match(out, /Only Party B acts as a Receiving Party under this Agreement; Party A is the sole Disclosing Party\./);
  assert.doesNotMatch(out, /Each party may act as both/);
});

test('zero carveouts renders "No carve-outs apply."', () => {
  const out = renderContract({ ...baseDeal, carveouts: [] }, template);

  assert.ok(out.includes('No carve-outs apply.'));
  assert.doesNotMatch(out, /^\s*1\. /m);
});

test('three carveouts render as a numbered list', () => {
  const carveouts = ['publicly available information', 'independently developed information', 'lawfully obtained from a third party'];
  const out = renderContract({ ...baseDeal, carveouts }, template);

  assert.ok(out.includes('1. publicly available information'));
  assert.ok(out.includes('2. independently developed information'));
  assert.ok(out.includes('3. lawfully obtained from a third party'));
  assert.doesNotMatch(out, /No carve-outs apply\./);
});

test('renderCarveouts handles empty vs populated arrays', () => {
  assert.equal(renderCarveouts([]), 'No carve-outs apply.');
  const list = renderCarveouts(['a', 'b']);
  assert.equal(list, '1. a\n2. b');
});

test('termYears = 0 throws with a helpful message', () => {
  assert.throws(
    () => validateDeal({ ...baseDeal, termYears: 0 }),
    (err) => err instanceof RangeError
      && /termYears/.test(err.message)
      && /greater than 0|expire immediately/.test(err.message),
  );
  assert.throws(() => renderContract({ ...baseDeal, termYears: 0 }, template), /termYears/);
});

test('other invalid input also throws helpfully', () => {
  assert.throws(() => validateDeal({ ...baseDeal, termYears: -1 }), RangeError);
  assert.throws(() => validateDeal({ ...baseDeal, mutual: 'yes' }), TypeError);
  assert.throws(() => validateDeal(null), TypeError);
});

